      ) VALUES (
        'pin-legend-sighisoara-9-84',
        'เส้นทางค้าโบราณและคาราวานปริศนา ซีกีชออารา (ดราคูลาคาพาเทียน)',
        'The Ancient Silk Route Oasis of Sighisoara (ดราคูลาคาพาเทียน)',
        'legend',
        'ทรานซิลเวเนีย (โรมาเนีย)',
        'Transylvania (Romania)',
        'ซีกีชออารา',
        'Sighisoara',
        46.1747,
        24.7483,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ทรานซิลเวเนีย (โรมาเนีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ดราคูลาคาพาเทียน ใน ซีกีชออารา',
        'A legendary monumental marvel in Transylvania (Romania). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ดราคูลาคาพาเทียน engineers in Sighisoara.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ทรานซิลเวเนีย (โรมาเนีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Transylvania (Romania), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ซีกีชออารา',
        'Do not deface, carve, or displace ancient stones in Sighisoara.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"เส้นทางค้าโบราณและคาราวานปริศนา ซีกีชออารา (ดราคูลาคาพาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

