      ) VALUES (
        'pin-sacred-catania-9-86',
        'พระธาตุยอดเขาพันยอด คาตาเนีย (กรีกซิซิเลียน)',
        'The Thousand-Spire Mountain Pagoda of Catania (กรีกซิซิเลียน)',
        'sacred',
        'ซิซิลี (อิตาลี)',
        'Sicily (Italy)',
        'คาตาเนีย',
        'Catania',
        37.4929,
        15.1323,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ซิซิลี (อิตาลี) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว กรีกซิซิเลียน เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Sicily (Italy), serving as the spiritual heart of ancestral กรีกซิซิเลียน heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ซิซิลี (อิตาลี) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Sicily (Italy), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน คาตาเนีย',
        'Remove footwear and maintain silence within the inner terrace of Catania.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"พระธาตุยอดเขาพันยอด คาตาเนีย (กรีกซิซิเลียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

