        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-sparta-9-88',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Night Livestock Stalker of Sparta (เฮลเลนิกโบราณ)',
        'monster',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0883,
        22.4597,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เพโลพอนนีส (กรีซ) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ สปาร์ตา',
        'Eyewitness reports of a formidable cryptid stalking Peloponnese (Greece). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Sparta.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เฮลเลนิกโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เฮลเลนิกโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ สปาร์ตา',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Sparta.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
