        'pin-curse-sparta-9-88',
        'คำสาปสะพานมรณะและลางบอกเหตุ สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Cursed Bridge Omen of Sparta (เฮลเลนิกโบราณ)',
        'curse',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0883,
        22.4597,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เพโลพอนนีส (กรีซ) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน สปาร์ตา',
        'A grim cautionary curse chronicle from Peloponnese (Greece). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Sparta.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เฮลเลนิกโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เฮลเลนิกโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ สปาร์ตา',
        'Never remove stones, relics, or votive offerings from Sparta.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"คำสาปสะพานมรณะและลางบอกเหตุ สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

