        37.0883,
        22.4597,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เพโลพอนนีส (กรีซ) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เฮลเลนิกโบราณ ใน สปาร์ตา',
        'A legendary monumental marvel in Peloponnese (Greece). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เฮลเลนิกโบราณ engineers in Sparta.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เพโลพอนนีส (กรีซ) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Peloponnese (Greece), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ สปาร์ตา',
        'Do not deface, carve, or displace ancient stones in Sparta.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"เกาะลอยน้ำและวิหารกลางบึงโบราณ สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
