        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-isafjordur-9-89',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ อีซาฟยอร์ดูร์ (นอร์สโบราณ)',
        'The Undeciphered Glyph Stele of Isafjordur (นอร์สโบราณ)',
        'legend',
        'เวสต์ฟยอร์ด (ไอซ์แลนด์)',
        'Westfjords (Iceland)',
        'อีซาฟยอร์ดูร์',
        'Isafjordur',
        66.1047,
        -23.155,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เวสต์ฟยอร์ด (ไอซ์แลนด์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว นอร์สโบราณ ใน อีซาฟยอร์ดูร์',
        'A legendary monumental marvel in Westfjords (Iceland). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral นอร์สโบราณ engineers in Isafjordur.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เวสต์ฟยอร์ด (ไอซ์แลนด์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Westfjords (Iceland), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ อีซาฟยอร์ดูร์',
        'Do not deface, carve, or displace ancient stones in Isafjordur.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ อีซาฟยอร์ดูร์ (นอร์สโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

