      ) VALUES (
        'pin-ghost-monte-alban-10-95',
        'เงาไร้หน้าที่บานหน้าต่างค่ำคืน มอนเตอัลบัน (ซาโปเทก)',
        'The Faceless Window Silhouette of Monte Alban (ซาโปเทก)',
        'ghost',
        'โออาฮากา (เม็กซิโก)',
        'Oaxaca (Mexico)',
        'มอนเตอัลบัน',
        'Monte Alban',
        17.0589,
        -96.7378,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น โออาฮากา (เม็กซิโก) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ มอนเตอัลบัน',
        'A chilling paranormal account from Oaxaca (Mexico). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Monte Alban.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ซาโปเทก ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ซาโปเทก oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ มอนเตอัลบัน',
        'Never whistle or look back if hearing whispers along twilight pathways in Monte Alban.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"เงาไร้หน้าที่บานหน้าต่างค่ำคืน มอนเตอัลบัน (ซาโปเทก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

