INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-philae-island-10-98',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง เกาะฟิเล (อียิปต์โบราณ)',
        'The Night Livestock Stalker of Philae Island (อียิปต์โบราณ)',
        'monster',
        'อัสวาน (อียิปต์)',
        'Aswan (Egypt)',
        'เกาะฟิเล',
        'Philae Island',
        23.9803,
        32.8392,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน อัสวาน (อียิปต์) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เกาะฟิเล',
        'Eyewitness reports of a formidable cryptid stalking Aswan (Egypt). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Philae Island.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว อียิปต์โบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native อียิปต์โบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เกาะฟิเล',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Philae Island.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง เกาะฟิเล (อียิปต์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-philae-island-10-98',
        'คำสาปสะพานมรณะและลางบอกเหตุ เกาะฟิเล (อียิปต์โบราณ)',
        'The Cursed Bridge Omen of Philae Island (อียิปต์โบราณ)',
        'curse',
        'อัสวาน (อียิปต์)',
        'Aswan (Egypt)',
        'เกาะฟิเล',
        'Philae Island',
        23.9803,
        32.8392,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง อัสวาน (อียิปต์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เกาะฟิเล',
        'A grim cautionary curse chronicle from Aswan (Egypt). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Philae Island.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อียิปต์โบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อียิปต์โบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เกาะฟิเล',
        'Never remove stones, relics, or votive offerings from Philae Island.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปสะพานมรณะและลางบอกเหตุ เกาะฟิเล (อียิปต์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-philae-island-10-98',
        'เกาะลอยน้ำและวิหารกลางบึงโบราณ เกาะฟิเล (อียิปต์โบราณ)',
        'The Artificial Floating Shrines of Philae Island (อียิปต์โบราณ)',
        'legend',
        'อัสวาน (อียิปต์)',
        'Aswan (Egypt)',
        'เกาะฟิเล',
        'Philae Island',
        23.9803,
        32.8392,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง อัสวาน (อียิปต์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว อียิปต์โบราณ ใน เกาะฟิเล',
        'A legendary monumental marvel in Aswan (Egypt). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral อียิปต์โบราณ engineers in Philae Island.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ อัสวาน (อียิปต์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Aswan (Egypt), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เกาะฟิเล',
        'Do not deface, carve, or displace ancient stones in Philae Island.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"เกาะลอยน้ำและวิหารกลางบึงโบราณ เกาะฟิเล (อียิปต์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-valley-of-the-kings-10-99',
        'มหาวิหารแห่งสันติภาพและศรัทธา หุบผากษัตริย์ (ทีบส์โบราณ)',
        'The Grand Peace Cathedral of Valley of the Kings (ทีบส์โบราณ)',
        'sacred',
        'ลักซอร์ (อียิปต์)',
        'Luxor (Egypt)',
        'หุบผากษัตริย์',
        'Valley of the Kings',
        25.7102,
        32.6014,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ลักซอร์ (อียิปต์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ทีบส์โบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Luxor (Egypt), serving as the spiritual heart of ancestral ทีบส์โบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ลักซอร์ (อียิปต์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Luxor (Egypt), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน หุบผากษัตริย์',
        'Remove footwear and maintain silence within the inner terrace of Valley of the Kings.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มหาวิหารแห่งสันติภาพและศรัทธา หุบผากษัตริย์ (ทีบส์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-valley-of-the-kings-10-99',
        'เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน หุบผากษัตริย์ (ทีบส์โบราณ)',
        'The Midnight Footsteps of Valley of the Kings (ทีบส์โบราณ)',
        'ghost',
        'ลักซอร์ (อียิปต์)',
        'Luxor (Egypt)',
        'หุบผากษัตริย์',
        'Valley of the Kings',
        25.7102,
        32.6014,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ลักซอร์ (อียิปต์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ หุบผากษัตริย์',
        'A chilling paranormal account from Luxor (Egypt). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Valley of the Kings.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ทีบส์โบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ทีบส์โบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ หุบผากษัตริย์',
        'Never whistle or look back if hearing whispers along twilight pathways in Valley of the Kings.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน หุบผากษัตริย์ (ทีบส์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

