        'Luxor (Egypt)',
        'หุบผากษัตริย์',
        'Valley of the Kings',
        25.7102,
        32.6014,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ลักซอร์ (อียิปต์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน หุบผากษัตริย์',
        'A grim cautionary curse chronicle from Luxor (Egypt). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Valley of the Kings.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ทีบส์โบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ทีบส์โบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ หุบผากษัตริย์',
        'Never remove stones, relics, or votive offerings from Valley of the Kings.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"อาถรรพ์รูปเคารพและดวงตาจ้องมอง หุบผากษัตริย์ (ทีบส์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

