        'pin-legend-valley-of-the-kings-10-99',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ หุบผากษัตริย์ (ทีบส์โบราณ)',
        'The Undeciphered Glyph Stele of Valley of the Kings (ทีบส์โบราณ)',
        'legend',
        'ลักซอร์ (อียิปต์)',
        'Luxor (Egypt)',
        'หุบผากษัตริย์',
        'Valley of the Kings',
        25.7102,
        32.6014,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ลักซอร์ (อียิปต์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ทีบส์โบราณ ใน หุบผากษัตริย์',
        'A legendary monumental marvel in Luxor (Egypt). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ทีบส์โบราณ engineers in Valley of the Kings.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลักซอร์ (อียิปต์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Luxor (Egypt), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ หุบผากษัตริย์',
        'Do not deface, carve, or displace ancient stones in Valley of the Kings.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ หุบผากษัตริย์ (ทีบส์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );